use rig::integrations::cli_chatbot::ChatBotBuilder;
use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
        .preamble("You are a helpful assistant.")
        .build();


    // Start the REPL. Type "exit" to quit.
    ChatBotBuilder::new().agent(agent).build().run().await?;


    Ok(())
}

use rig::embeddings::EmbeddingsBuilder;
use rig::integrations::cli_chatbot::ChatBotBuilder;
use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};
use rig::vector_store::in_memory_store::InMemoryVectorStore;


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let client = OpenAI::from_env()?;
    let embedding_model = client.embedding(openai::TEXT_EMBEDDING_3_SMALL, None).erase();


    let embeddings = EmbeddingsBuilder::new(embedding_model.clone())
        .documents(vec![
            "Rig is a Rust library for building LLM applications.".to_string(),
            "A Rig agent combines a model, a preamble, context and tools.".to_string(),
        ])?
        .build()
        .await?;
    let index = InMemoryVectorStore::from_documents(embeddings).index(embedding_model);


    let agent = AgentBuilder::new(client.completion(openai::GPT_5_5))
        .preamble("Answer using the retrieved context.")
        .dynamic_context(2, index)
        .build();


    ChatBotBuilder::new().agent(agent).build().run().await?;


    Ok(())
}

use rig::completion::PromptError;
use rig::integrations::cli_chatbot::{Chat, ChatBotBuilder};
use rig::message::Message;
use rig::wasm_compat::WasmCompatSend;


/// Replies with the length of the conversation so far.
struct Echo;


impl Chat for Echo {
    async fn chat(
        &self,
        prompt: impl Into<Message> + WasmCompatSend,
        history: &mut Vec<Message>,
    ) -> Result<String, PromptError> {
        let prompt: Message = prompt.into();
        history.push(prompt);
        let reply = format!("turn {}", history.len());
        history.push(Message::assistant(reply.clone()));
        Ok(reply)
    }
}


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    ChatBotBuilder::new().chat(Echo).build().run().await?;
    Ok(())
}
